/* English content for Siyer Yolum (loaded with the app, used when the language is English).
   Same order and structure as data.js. Lesson entry:
   id: [title, kidsSummary, [[heading, text] x3], adultSummary, [[heading, text] x3], [[question, [options], explanation] x2], [detail paragraphs]]
   Dates follow the TDV Encyclopedia of Islam (DİA) "Muhammed" article and its chronology; sources cited in Turkish stay as they are. */
const EN = {
 donem: { cocukluk: 'Childhood', genclik: 'Youth', mekke: 'Meccan Period', medine: 'Medinan Period', vefat: 'Passing', halifeler: 'Era of the Four Caliphs' },
 sinav: { 's-cocukluk': 'Childhood Quiz', 's-genclik': 'Youth Quiz', 's-oncesi': 'Before Prophethood', 's-mekke': 'Meccan Period Quiz', 's-medine': 'Medinan Period Quiz', 's-sonrasi': 'After Prophethood', 's-halifeler': 'Four Caliphs Quiz' },
 yer: { mekke: 'Mecca', medine: 'Medina', taif: 'Ta’if', bedir: 'Badr', ebva: 'Abwa’', kudeyd: 'Qudayd', cidde: 'Jeddah', hudeybiye: 'Hudaybiyya', arafat: 'Arafat', busra: 'Busra', sam: 'Damascus', kudus: 'Jerusalem', habes: 'Abyssinia (Aksum)', sana: 'Sana‘a', kufe: 'Kufa', basra: 'Basra' },
 ders: {
  fil: ['The Year of the Elephant and the Birth',
   'A much-loved baby was born: Muhammad (peace be upon him)!',
   [['The elephant came', 'Abraha came with huge elephants to destroy the Ka‘ba.'], ['The birds arrived', 'Allah sent small birds and the army scattered.'], ['A baby was born', 'In that same year the Prophet was born in Mecca.']],
   'He was born in Mecca on a Monday, 12 Rabi‘ al-Awwal, fifty (or fifty-five) days after the Elephant incident. According to DİA the date is 20 April 571 (another account says 569).',
   [['The Elephant incident', 'Abraha, the governor of Yemen, marched on Mecca to destroy the Ka‘ba; his army was destroyed. The Arabs called that year the “Year of the Elephant”.'], ['Birth', 'Monday, 12 Rabi‘ al-Awwal, Mecca. There are two accounts for the Gregorian date: 20 April 571 (al-Falaki’s calculation, DİA text) and 17 June 569 (DİA chronology table).'], ['Family', 'His mother was Amina bint Wahb and his father Abdullah ibn Abdul-Muttalib. His lineage goes back to Prophet Ishmael.']],
   [['In the year of which event was the Prophet born?', ['The Hijra', 'The Elephant incident', 'The Battle of Badr'], 'The birth coincides with the year of the Elephant incident.'], ['What did Abraha want to destroy?', ['The Prophet’s Mosque', 'The Ka‘ba', 'Masjid al-Aqsa'], 'His target was the Ka‘ba.']],
   ['The causes, date and outcome of the Elephant incident are told differently in the sources. Its protagonist Abraha was the governor of Yemen under the Abyssinian kingdom, a zealous Christian. Seeing Arabs travel to Mecca to visit the Ka‘ba, he had a great cathedral built in Sana‘a to draw people there.', 'In the 105th chapter of the Qur’an the soldiers are called “ashab al-fil” (people of the elephant). Because an elephant stood before the army, both the chapter and the event are called “al-Fil”, the Elephant.', 'According to the prevailing view, Muhammad was born fifty (or fifty-five) days after this event, on a Monday, 12 Rabi‘ al-Awwal, in Mecca. DİA gives two Gregorian calculations together: 20 April 571 and 17 June 569.']],
  sut: ['His Wet Nurse Halima',
   'Little Muhammad grew up for a while in the desert with his wet nurse Halima.',
   [['Going to the desert', 'In Mecca, babies were sent to families in the desert so they would grow up healthy.'], ['Halima', 'Halima of the Sa‘d tribe took him in and loved him very much.'], ['Back to Mecca', 'After two years he was brought to his mother; she sent him back to the desert for a while because the air suited him.']],
   'Following Meccan custom he was given to a Bedouin wet nurse: Halima bint Abu Dhu’ayb of the Banu Sa‘d ibn Bakr branch of Hawazin. He spent the first two years of his childhood with her.',
   [['The wet-nursing tradition', 'Meccans gave their children to Bedouins for a healthy climate and pure Arabic.'], ['Halima', 'The first two years were spent with his wet nurse Halima, her husband Harith and his foster siblings Abdullah, Unaysa and Shayma’. After two years he was brought to Mecca; because the desert air suited him (or, in one account, because plague broke out in Mecca) Amina sent him back to Halima for a while.'], ['Return', 'At about five years old he was brought back to Mecca by his wet nurse and handed over to his mother.']],
   [['Who was the Prophet’s wet nurse?', ['Halima', 'Umm Ayman', 'Khadija'], 'His wet nurse was Halima.'], ['Why were children sent to the desert?', ['To learn trade', 'To grow up healthy and learn good Arabic', 'To prepare for war'], 'For the desert air and pure language.']],
   ['Meccan families gave their children to a wet nurse from the Bedouin tribes so that they would grow up in the healthy desert air and learn pure Arabic. Women for whom wet-nursing was a source of income preferred children of wealthy families.', 'Halima belonged to the Banu Sa‘d ibn Bakr branch of the Hawazin tribe. When she came to Mecca in a year of famine she could not find a child from a rich family; she hesitated to take Muhammad because he was an orphan, but accepted so as not to go home empty-handed.', 'After two years Halima weaned the child and brought him to his family. Seeing that the desert air agreed with him (in one account, because plague had struck Mecca), Amina sent him back for a while. When Muhammad turned five, Halima handed him over to his family.']],
  amine: ['Loss of His Mother and Grandfather',
   'Little Muhammad lost his mother, then his grandfather. His uncle Abu Talib took care of him.',
   [['His mother passed away', 'Amina died at Abwa’ on the way back from Medina.'], ['His grandfather', 'His grandfather Abdul-Muttalib looked after him very well.'], ['His uncle', 'After his grandfather, his uncle Abu Talib took him into his home.']],
   'He lost his mother at six and his grandfather at eight, and came under the protection of Abu Talib.',
   [['Amina’s death', 'Amina visited her relatives in Yathrib with her son; after staying about a month she fell ill on the way back and died at Abwa’, about 190 km from Medina. His nurse Umm Ayman took him to Mecca and handed him to Abdul-Muttalib.'], ['Abdul-Muttalib', 'Abdul-Muttalib treated him with great care and took him along to the meetings at Dar al-Nadwa. About two years later he too died and Muhammad was entrusted to his uncle Abu Talib.'], ['Abu Talib', 'By his grandfather’s will, his uncle Abu Talib took him in and protected him for the rest of his life.']],
   [['Where did Amina die?', ['In Mecca', 'At Abwa’', 'In Damascus'], 'She died at Abwa’ on the way back from Medina.'], ['Who took care of the Prophet after his grandfather?', ['Abu Lahab', 'Hamza', 'Abu Talib'], 'His uncle Abu Talib looked after him.']],
   ['Amina was the daughter of Wahb ibn Abd Manaf of the Banu Zuhra branch of Quraysh. She visited her relatives in Yathrib with her son; after about a month there she fell ill on the way back and died at Abwa’, about 190 km from Medina. His nurse Umm Ayman took the child to Mecca and handed him over to his grandfather Abdul-Muttalib.', 'Abdul-Muttalib’s real name was Shayba; he was born in Yathrib. When he arrived in Mecca with his uncle Muttalib, the Meccans took him for a slave and called him “Abd al-Muttalib”, and the name stuck. He rediscovered the Zamzam well and took on the duty of giving water to pilgrims. He cared deeply for his grandson and took him along to the Dar al-Nadwa meetings.', 'Before dying, Abdul-Muttalib entrusted the care of his eight-year-old grandson to Abu Talib. Abu Talib was Abdullah’s full brother, and the leadership of Banu Hashim stayed with him until his death.']],
  sam: ['The Journey to Syria',
   'At twelve he joined his uncle’s caravan and met a monk named Bahira on the way.',
   [['The caravan', 'Abu Talib went to Syria for trade and took Muhammad along.'], ['New places', 'On the road he saw new cities and new people.'], ['Shepherding', 'Even earlier, as a boy, he had herded sheep to help his uncle.']],
   'He set out on a trading journey to Syria with his uncle Abu Talib. There is a report that he met the monk Bahira on this journey; scholars discuss it in separate DİA entries (Bahîrâ, Busrâ).',
   [['Trade routes', 'Meccan trade routes stretched to Syria and Yemen; in later years the Prophet also travelled to Damascus, Yemen and Abyssinia.'], ['Shepherding', 'It is known that around the age of ten he herded sheep to help Abu Talib, who had a large family; he later said, “Every prophet has tended sheep.”'], ['Date', 'The age and year of the journey vary by source; the DİA chronology places his trip to Syria with Abu Talib in his childhood years.']],
   [['Who did the Prophet go to Syria with as a child?', ['His grandfather', 'His uncle Abu Talib', 'Khadija'], 'He went with his uncle Abu Talib.'], ['What job did the Prophet do as a child?', ['He herded sheep', 'Blacksmithing', 'Sailing'], 'It is known that he herded sheep around the age of ten.']],
   ['Meccan trade routes stretched to Syria and Yemen. It is known that Muhammad later went to the fair at Hubasha, once or twice to Yemen, to fairs in eastern Arabia, and to Abyssinia; these journeys let him get to know people, languages and customs.', 'Busra is an ancient city in southern Syria, near the source of the Yarmouk river and about 141 km south of Damascus; it was a stopping place for Meccan caravans. The report that he met the monk Bahira on a journey to Syria as a child is told with varying details in the sources and is discussed separately by scholars.']],
  fudul: ['Hilf al-Fudul and “al-Amin”',
   'Everyone trusted him and called him “al-Amin”.',
   [['Al-Amin', 'Because of his honesty he was called al-Amin, “the trustworthy”.'], ['Standing with the wronged', 'He joined an alliance that protected people who were treated unjustly.'], ['Shepherd and trader', 'As a young man he herded sheep, then traded.']],
   'In his youth he took part in the Ficar war with his uncles (without fighting), then joined the Hilf al-Fudul; he became known as “al-Amin” for his honesty.',
   [['Hilf al-Fudul', 'An alliance formed right after the Ficar war, based on an oath to protect the wronged. After becoming a prophet he praised it.'], ['The Ficar War', 'He took part with his uncles in the fourth of the first group of Ficar wars but did not actually fight. His age at the time is given as 14, 15, 17 or 20.'], ['Al-Amin', 'Because of his truthfulness and keeping of trusts, the Meccans called him al-Amin.']],
   [['What does “al-Amin” mean?', ['Brave', 'Trustworthy', 'Rich'], 'Al-Amin means trustworthy.'], ['What was the aim of Hilf al-Fudul?', ['To protect the wronged', 'To raid caravans', 'To declare war'], 'To protect those treated unjustly.']],
   ['Ficar means “to deviate from what is right, to sin”. Four wars were named this way because they were fought in the sacred months (Dhu al-Qa‘da, Dhu al-Hijja, Muharram, Rajab). Muhammad took part with his uncles in the fourth of the first group but did not actually fight. His age at that time is given as 14, 15, 17 or 20.', 'Right after this war he attended the Hilf al-Fudul gathering, whose members swore to protect the wronged. After becoming a prophet he spoke of this alliance with praise and said he would not hesitate if invited to such a pact again.']],
  hatice: ['Marriage to Khadija',
   'Muhammad (peace be upon him) married Khadija and they built a happy home.',
   [['Trade', 'Khadija gave the trustworthy Muhammad goods to trade.'], ['Marriage', 'They married; Khadija became his greatest supporter.'], ['Children', 'His daughters were Zaynab, Ruqayya, Umm Kulthum and Fatima.']],
   'At twenty-five he married Khadija; in the years that followed she was his greatest supporter.',
   [['Trade partnership', 'He travelled to Syria with the goods of Khadija bint Khuwaylid; her servant Maysara was in the caravan too. His honesty and profits impressed Khadija.'], ['Marriage', 'His uncles asked for Khadija from her uncle Amr ibn Asad; after the marriage Muhammad moved from Abu Talib’s house to Khadija’s. It is said he was twenty-five and Khadija forty at the time; but because she bore seven (or six) children, DİA finds the age of twenty-eight, reported from Ibn Abbas, more plausible.'], ['Children', 'His daughters were Zaynab, Ruqayya, Umm Kulthum and Fatima. His son Ibrahim was from Maria.']],
   [['Who was the Prophet’s first wife?', ['Aisha', 'Khadija', 'Hafsa'], 'His first wife was Khadija.'], ['Which of these was a daughter of the Prophet?', ['Shayma’', 'Fatima', 'Sumayya'], 'Fatima was his daughter.']],
   ['Khadija was born in Mecca; her lineage joins the Prophet’s at Qusayy. Because of her great chastity she was called “al-Tahira” (the pure) before Islam. She had been married twice before marrying Muhammad.', 'The sources say he was 25 and Khadija 40 at the time of the marriage; DİA, considering the number of her children, finds the age of 28 reported from Ibn Abbas more plausible. The Prophet remembered Khadija with loyalty even after the Hijra.']],
  hacer: ['Arbitration over the Black Stone',
   'He prevented a big quarrel while the Ka‘ba was being rebuilt.',
   [['Rebuilding the Ka‘ba', 'The Meccans rebuilt the Ka‘ba.'], ['The Black Stone', 'They argued over who would put the Black Stone back in place.'], ['A clever solution', 'He placed the stone on a cloth and each tribe held one end.']],
   'When the Ka‘ba was rebuilt he settled the dispute over setting the Black Stone with a fair method.',
   [['Rebuilding the Ka‘ba', 'Quraysh rebuilt the Ka‘ba in 605 CE.'], ['The dispute', 'The tribes prepared for war over the honour of setting the Black Stone.'], ['Arbitration', 'On Abu Umayya ibn al-Mughira’s proposal, they agreed to follow the decision of the first person to enter through the Banu Shayba Gate; it was Muhammad. He placed the stone on a cloth, had the tribal leaders lift it together, and set it in place with his own hands.']],
   [['What was the dispute during the rebuilding?', ['The place of the door', 'Who would set the Black Stone', 'The cost'], 'They argued over who would set the stone.'], ['How did the Prophet have the stone carried?', ['He carried it alone', 'On a cloth held by the tribes', 'With an elephant'], 'Everyone held an end of the cloth.']],
   ['The Black Stone (al-Hajar al-Aswad) is about 30 cm across, egg-shaped, dark reddish-black, and sits about 1.5 m above the ground. The sources agree that Prophet Abraham placed it while building the Ka‘ba to mark the starting point of the circumambulation.', 'When Quraysh rebuilt the Ka‘ba in 605 CE, they argued over who should set the stone, to the point of risking war. On Abu Umayya ibn al-Mughira’s proposal they agreed to follow the decision of the first to enter by the Banu Shayba Gate. It was Muhammad: he put the stone on a cloth, the tribal chiefs lifted it together, and he set it in place with his own hands.']],
  hira: ['Reflection at Hira',
   'Muhammad (peace be upon him) loved to be alone in the Cave of Hira and think.',
   [['Mount of Light', 'He would climb to the Cave of Hira near Mecca.'], ['Reflection', 'He thought about creation and worshipped Allah.'], ['True dreams', 'The dreams he saw came true exactly.']],
   'As he approached forty he withdrew to the Cave of Hira for reflection; true dreams were the beginning of revelation.',
   [['Retreat', 'In Ramadan he stayed at Hira for days, returning to Khadija when his food ran out.'], ['True dreams', 'The first sign of revelation was true dreams that came true like the light of dawn.'], ['Distance from society', 'He was uneasy with the immorality of idol-worshipping Mecca and never worshipped idols.']],
   [['Where did the Prophet go for retreat?', ['The Cave of Thawr', 'The Cave of Hira', 'Mount Uhud'], 'The Cave of Hira.'], ['What was the first sign of revelation?', ['True dreams', 'Seeing fire', 'Hearing voices'], 'Dreams that came true.']],
   ['Hira lies northeast of Mecca, about 5 km from the Ka‘ba, and is also known as Jabal al-Nur (Mount of Light). The mountain is steeper and higher than those around it; the famous cave is about 20 m below the summit.', 'In the years before prophethood Muhammad would withdraw here in Ramadan to reflect. Revelation also began in this cave.']],
  vahiy: ['The First Revelation',
   'Gabriel came and said “Read!” Prophethood began.',
   [['Read!', 'Gabriel said “Iqra” at Hira and the first verses came down.'], ['Fear', 'The Prophet went home trembling and Khadija calmed him.'], ['First believers', 'Khadija, Abu Bakr, Ali and Zayd were among the first to believe.']],
   'In Ramadan (the 27th night in the DİA chronology, marked with a question mark), prophethood began in the Cave of Hira with the first five verses of Surat al-Alaq (610).',
   [['The first verses', 'Gabriel said “Read!” and the verses “Read in the name of your Lord who created…” came down.'], ['Khadija’s support', 'Khadija comforted the Prophet when he came home shaken and took him to her cousin Waraqa ibn Nawfal.'], ['First believers', 'Khadija, Abu Bakr, Ali and Zayd ibn Haritha were among the first Muslims.']],
   [['In which chapter were the first verses revealed?', ['Al-Fatiha', 'Al-Alaq', 'Al-Baqara'], 'The first five verses of Surat al-Alaq.'], ['Through which angel did revelation first come?', ['Gabriel', 'Michael', 'Israfil'], 'Through Gabriel.']],
   ['Wahy (revelation) means in the dictionary “to speak quickly and secretly, to hint, to inspire”; as a term, it is God’s secretly informing His prophet of a command or knowledge. In the Qur’an it appears in verb forms in more than seventy places.', 'Scholars of the Prophet’s biography agree that Gabriel taught the Messenger of God ablution and prayer when he brought the first revelation. After the shock of the first revelation there was a pause; the Prophet often went to Hira waiting for Gabriel to appear again, and was troubled by the fear that his Lord had left him.']],
  gizli: ['The Secret Call',
   'For the first three years he told only people he trusted about Islam.',
   [['Quiet invitation', 'He first invited close friends to Islam.'], ['The house of Arqam', 'Muslims gathered and learned in Arqam’s house.'], ['New members', 'People like Uthman, Zubayr and Talha became Muslims.']],
   'The call continued secretly for about three years. First his wife Khadija, then Abu Bakr, Ali, Zayd ibn Haritha and his daughters Zaynab, Ruqayya and Umm Kulthum became Muslims; Dar al-Arqam became a meeting place.',
   [['Inviting trusted people', 'Through Abu Bakr’s efforts Uthman, Zubayr, Abd al-Rahman ibn Awf, Sa‘d ibn Abi Waqqas and Talha became Muslims.'], ['Dar al-Arqam', 'The house of Arqam ibn Abi al-Arqam; Muslims gathered here until Umar became a Muslim (DİA chronology: 616).'], ['Prayer', 'Muslims prayed morning and evening, keeping their worship secret.']],
   [['About how many years did the secret call last?', ['1', '3', '10'], 'About three years.'], ['Whose house did the Muslims gather in?', ['Abu Bakr’s', 'Arqam’s', 'Abu Talib’s'], 'In Arqam’s house.']],
   ['The call continued secretly for about three years. The Prophet chose the house of Arqam ibn Abi al-Arqam, at the foot of Mount Safa within the Sacred Mosque, as his base. There he taught the Companions religious knowledge, invited seekers of divine truth to Islam, recited the Qur’an to them and prayed with them.', 'Reasons for choosing the house included that it lay within the Sacred Precinct and made it easy to meet Meccans and visitors without attracting attention during the pilgrimage and umra seasons. Umar accepted Islam here too. The sources use the house to date when Companions became Muslims.']],
  acik: ['The Open Call and Persecution',
   'On Mount Safa the Prophet called everyone to Islam. The polytheists tormented the Muslims.',
   [['Mount Safa', 'He told everyone loudly about the oneness of Allah.'], ['Abu Lahab', 'His uncle Abu Lahab opposed him.'], ['Patience', 'Companions like Bilal and Sumayya endured torture.']],
   'From the 4th year of prophethood (613) the call was made openly; the Quraysh polytheists pressured and tortured the Muslims.',
   [['The open call', 'Upon the command “Warn your closest relatives” (26:214) he first invited his close relatives to a meal; about forty-five people from Banu Hashim and Banu al-Muttalib came. His uncle Abu Lahab opposed him.'], ['Opposition', 'Quraysh leaders like Abu Lahab and Abu Jahl mocked and pressured him.'], ['Torture', 'Slaves and the weak, such as Bilal al-Habashi and the family of Yasir (Sumayya, Ammar), were severely tortured.']],
   [['From which hill did the open call begin?', ['Safa', 'Uhud', 'Hira'], 'From Mount Safa.'], ['Which of these was a tortured Companion?', ['Bilal al-Habashi', 'Mus‘ab ibn Umayr', 'Umar'], 'Bilal al-Habashi was severely tortured.']],
   ['When commanded to make the call openly, the Prophet first invited his close relatives to a meal; about forty-five people from Banu Hashim and Banu al-Muttalib came. His uncle Abu Lahab opposed him.', 'Before prophethood Abu Lahab had been Muhammad’s friend; he had married his two sons to the Prophet’s daughters Ruqayya and Umm Kulthum. After Muhammad became a prophet, he opposed him fiercely. In this period the weak Muslims, such as Bilal al-Habashi, began to be tortured.']],
  habese: ['Migration to Abyssinia',
   'The Muslims went to the land of the just Abyssinian king, the Negus.',
   [['The journey', 'A group of Muslims went to Abyssinia to find safety.'], ['The Negus', 'The just king, the Negus, protected them.'], ['Surat Maryam', 'Ja‘far recited Surat Maryam before the king.']],
   'To escape pressure, a group of eleven men and four women migrated to Abyssinia in 615, including Uthman and his wife Ruqayya. It was the first migration in Islam. A second migration followed in 616.',
   [['The first migration', 'Unable to stop the persecution, the Prophet permitted migration to the land of the Christian Negus Ashama (615).'], ['Quraysh envoys', 'Quraysh sent Amr ibn al-As with gifts to the Negus to demand the Muslims back.'], ['Ja‘far ibn Abi Talib', 'The Muslims’ spokesman Ja‘far recited Surat Maryam; the Negus protected the Muslims.']],
   [['To which country did the Muslims migrate?', ['Abyssinia', 'Egypt', 'Yemen'], 'To Abyssinia.'], ['Who was the spokesman of the migrating Muslims?', ['Ja‘far', 'Umar', 'Ali'], 'Ja‘far ibn Abi Talib.']],
   ['Unable to stop the persecution, the Prophet allowed some Muslims to migrate to Abyssinia, the land of the Christian Negus Ashama. A group of eleven men and four women, including Uthman and his wife Ruqayya, went in 615. This was the first migration in Islam.', 'Quraysh sent a delegation to demand the Muslims back, but the Negus refused; he also rejected a second delegation after Badr. Thirty-three of the Abyssinian emigrants returned to Mecca after the boycott ended (620). Some of the rest came to Medina after the Hijra and others in year 7 (628).']],
  boykot: ['The Boycott Years',
   'The Meccans did not trade with the Muslims for three years. They were very hard days.',
   [['The boycott', 'Quraysh stopped speaking and trading with the Muslims.'], ['Shi‘b Abi Talib', 'The Muslims lived in a valley and food was hard to find.'], ['It ended', 'After three years the boycott was lifted.']],
   'Quraysh imposed a social and economic boycott on Banu Hashim and Banu al-Muttalib from 617 to 620 (it is also reported to have lasted less).',
   [['The document', 'Quraysh decided not to speak or trade with them, wrote the terms on a sheet and hung it on the wall of the Ka‘ba. Abu Talib gathered his nephew and his people in his own quarter.'], ['Shi‘b Abi Talib', 'During the boycott the fortunes of Khadija and Abu Talib were used up; there was no trade except in the pilgrimage season.'], ['End of the boycott', 'Zuhayr ibn Umayya and Hisham ibn Amr, with Mut‘im ibn Adi and Zam‘a ibn al-Aswad, agreed to end the boycott (620).']],
   [['How many years did the boycott last?', ['1', '3', '7'], 'Between 617 and 620, about three years.'], ['Where did the Muslims stay during the boycott?', ['In Shi‘b Abi Talib', 'In Medina', 'In Abyssinia'], 'In Shi‘b Abi Talib.']],
   ['Quraysh decided not to speak or trade with Banu Hashim and Banu al-Muttalib (except Abu Lahab and his sons); they wrote the terms on a sheet and hung it on the wall of the Ka‘ba. Abu Talib gathered his nephew and his followers in his own quarter (Shi‘b Abi Talib).', 'According to DİA the boycott covered 617–620, though it is also reported to have lasted less. Khadija’s and Abu Talib’s wealth was used up, and there was no trade outside the pilgrimage season. Abu Talib’s nephew Zuhayr ibn Umayya and Hisham ibn Amr agreed with Mut‘im ibn Adi and Zam‘a ibn al-Aswad to end the boycott.']],
  huzun: ['The Year of Sorrow',
   'In the same year Abu Talib and Khadija both passed away. That year was called the “Year of Sorrow”.',
   [['Khadija', 'His beloved wife Khadija passed away.'], ['Abu Talib', 'About a month later his protector uncle passed away too.'], ['Year of Sorrow', 'That year was called “Amm al-Huzn”.']],
   'In the 10th year of prophethood (620) first Khadija, then about a month later Abu Talib passed away; this year was called the “year of sorrow” (‘am al-huzn).',
   [['Khadija’s death', 'She died on 10 Ramadan / 19 April 620.'], ['Abu Talib’s death', 'He died about a month later (Shawwal); there are different accounts of the dates.'], ['Result', 'As the polytheists’ pressure grew, the Prophet looked for new ways to spread the call.']],
   [['Who died in the Year of Sorrow?', ['Hamza and Umar', 'Abu Talib and Khadija', 'Abdul-Muttalib and Amina'], 'Khadija and, about a month later, Abu Talib.'], ['What is this year called?', ['Year of the Elephant', 'Amm al-Huzn', 'Year of the Hijra'], 'Amm al-Huzn (the Year of Sorrow).']],
   ['In the 10th year of prophethood, first Khadija (10 Ramadan / 19 April 620), then about a month later Abu Talib passed away. There are different accounts of their death dates. This year was called “sanat al-huzn” (the year of sorrow).', 'With Abu Talib’s protection gone, it became harder to protect the Prophet in Mecca as before, and he began looking for new paths: first Ta’if, then meetings with groups from Medina during the pilgrimage season.']],
  taif: ['The Journey to Ta’if',
   'He went to tell the people of Ta’if about Islam but was stoned. Still, he did not curse them.',
   [['He walked to Ta’if', 'He went to Ta’if with Zayd ibn Haritha.'], ['They were stoned', 'The people of Thaqif drove them out and stoned them.'], ['He prayed', 'Though wounded, he prayed instead of cursing.']],
   'In the year of sorrow (Shawwal 620) the Prophet went to Ta’if, home of the Thaqif tribe, with Zayd ibn Haritha; he was rejected and returned to Mecca under the protection of Mut‘im ibn Adi.',
   [['Going to Ta’if', 'He invited the three sons of Amr ibn Umayr and other notables of the tribe to Islam; none accepted.'], ['The stoning', 'Thaqif set ruffians and children on them; Zayd and the Prophet were wounded.'], ['Mut‘im ibn Adi', 'To enter Mecca he needed the protection of a Qurayshi; many he asked refused, and finally Mut‘im ibn Adi, chief of Banu Nawfal, took him under his protection.']],
   [['Who did the Prophet go to Ta’if with?', ['Zayd ibn Haritha', 'Abu Bakr', 'Ali'], 'With Zayd ibn Haritha.'], ['How did he respond when stoned?', ['He cursed them', 'He prayed for them', 'He got angry'], 'He did not curse; he prayed for their guidance.']],
   ['Ta’if lies 88 km east of Mecca in the Wajj valley, about 1,700 m above sea level; it is the coldest city of the Hijaz in winter, and in summer was the resort of the Meccan elite. The Prophet went to this city, home of the Thaqif tribe, with Zayd ibn Haritha.', 'He invited the three sons of Amr ibn Umayr (Abd Yalil, Mas‘ud and Habib) and other important people of the tribe to Islam; the Thaqif, who had kinship and trade ties with Quraysh, refused. To enter Mecca he needed a Qurayshi’s protection; many he asked refused, and finally Mut‘im ibn Adi, chief of Banu Nawfal, took him under his protection.', 'When Aisha later asked whether he had known a harder day than Uhud, the Messenger of God told of his return from Ta’if.']],
  isra: ['Isra and Mi‘raj',
   'One night he travelled from the Sacred Mosque to Masjid al-Aqsa, and from there ascended to the heavens. Prayer was made obligatory.',
   [['The Isra', 'He travelled from Mecca to Jerusalem in one night.'], ['The Mi‘raj', 'From there he ascended through the seven heavens.'], ['Prayer', 'The five daily prayers were made obligatory this night.']],
   'According to the DİA chronology, the Isra and Mi‘raj took place on 27 Rajab 621; the five daily prayers were made obligatory.',
   [['The Isra', 'The journey from the Sacred Mosque to Masjid al-Aqsa is mentioned in the Qur’an.'], ['The Mi‘raj', 'The Prophet was raised to the heavens, met various prophets and reached the divine presence.'], ['Prayer', 'Prayer, which began as fifty daily, was reduced to five on Moses’s advice.']],
   [['Between which two mosques was the Isra?', ['Sacred Mosque – Masjid al-Aqsa', 'The Prophet’s Mosque – Quba', 'Quba – Masjid al-Aqsa'], 'Between the Sacred Mosque and Masjid al-Aqsa.'], ['Which act of worship was made obligatory that night?', ['Fasting', 'Zakat', 'Prayer'], 'The five daily prayers.']],
   ['The Isra refers to the Prophet’s journey during the Mi‘raj from the Sacred Mosque to Masjid al-Aqsa; it is mentioned in the first verse of Surat al-Isra. The DİA chronology places the Isra and Mi‘raj on 27 Rajab 621 and notes that the five daily prayers were made obligatory with this event.', 'In the Siyer Vakfı Meccan lecture series, this event and the process stretching from Ta’if to the Aqaba meetings are discussed together.']],
  akabe: ['The Pledges of Aqaba',
   'Muslims from Medina made a promise to the Prophet and invited him to Medina.',
   [['First Aqaba', 'The Medinans pledged to Islam and to the Prophet at Aqaba.'], ['Mus‘ab', 'Mus‘ab ibn Umayr was sent to Medina as a teacher.'], ['Second Aqaba', 'A year later more people came and invited him to Medina.']],
   'The two Pledges of Aqaba with groups from the Aws and Khazraj of Medina during the pilgrimage season prepared the ground for the Hijra.',
   [['First Aqaba (621)', 'In the pilgrimage season of 620 six men of the Khazraj became Muslims. The next year twelve of them (ten Khazrajis, two from the Aws) met secretly at Aqaba and pledged conditions such as not associating anyone with God and not stealing or committing adultery.'], ['Mus‘ab ibn Umayr', 'Mus‘ab was sent to Medina to teach the Qur’an and Islam; Islam spread quickly in Medina.'], ['Second Aqaba (622)', 'In the pilgrimage season seventy-five Yathribites, two of them women, met at Aqaba and promised to protect the Prophet and the Meccan Muslims as they protected their own lives.']],
   [['Who was sent to Medina as a teacher?', ['Abu Bakr', 'Mus‘ab ibn Umayr', 'Ali'], 'Mus‘ab ibn Umayr.'], ['With whom were the Pledges of Aqaba made?', ['The Medinans', 'The Abyssinians', 'The people of Ta’if'], 'With the Aws and Khazraj of Medina.']],
   ['Aqaba means in the dictionary “a steep path, a hard-to-climb mountain pass”. In the 620 pilgrimage season a group of Khazrajis met the Prophet at Aqaba and became Muslims; As‘ad ibn Zurara returned to Yathrib and told people about the new religion.', 'The next year twelve people (ten Khazrajis, two from the Aws) met secretly at Aqaba and pledged conditions such as not associating anyone with God and not stealing or committing adultery (First Aqaba). Mus‘ab ibn Umayr was sent as a teacher.', 'In the following pilgrimage season seventy-five Yathribites, two of them women, came and promised to protect the Prophet and the Meccan Muslims as they protected themselves (Second Aqaba). Permission to migrate was then given; the first to go was Amir ibn Rabi‘a with his wife Layla.']],
  hicret: ['The Hijra',
   'The Prophet and Abu Bakr went from Mecca to Medina. On the way they hid in a cave.',
   [['He set out at night', 'Ali slept in his bed and kept the polytheists busy.'], ['The Cave of Thawr', 'He hid in the cave with Abu Bakr for three days.'], ['Welcome in Medina', 'The Medinans welcomed him with “Tala‘a al-badru ‘alayna”.']],
   'After the polytheists’ assassination plot, the Prophet migrated from Mecca to Medina with Abu Bakr (622).',
   [['The assassination plot', 'Quraysh chose a young man from each tribe to kill the Prophet; Ali slept in his bed.'], ['The Cave of Thawr', 'The Prophet and Abu Bakr stayed three days in Thawr; Allah protected them from the polytheists.'], ['Arrival in Medina', 'He left Thawr on 13 September 622; reached Quba on 8 Rabi‘ al-Awwal / 20 September and founded the Quba Mosque. On 12 Rabi‘ al-Awwal / 24 September he led the first Friday prayer in the Ranuna valley, reached Medina the same day and settled in the house of Abu Ayyub al-Ansari.']],
   [['Who slept in the Prophet’s bed during the Hijra?', ['Abu Bakr', 'Ali', 'Umar'], 'Ali slept there.'], ['Which cave did the Prophet hide in during the Hijra?', ['Hira', 'Thawr', 'Arqam'], 'The Cave of Thawr.']],
   ['The Hijra as a term refers especially to the migration of the Prophet and the Meccan Muslims to Medina. Those who migrated were called muhajirun and the Medinans who helped them ansar. The word “hijra” does not appear in the Qur’an, but derivatives of the same root occur thirty-one times in twenty-seven verses.', 'The polytheists met at Dar al-Nadwa and decided to kill the Prophet (26 Safar / 9 September 622). That night the Prophet left Mecca with Abu Bakr and hid in a cave on Mount Thawr; Quraysh promised 100 camels to whoever captured him. Three days later, with camels brought by their guide, they set out toward Yathrib (1 Rabi‘ al-Awwal / 13 September).', 'On 8 Rabi‘ al-Awwal / 20 September they reached Quba and founded the Quba Mosque. On 12 Rabi‘ al-Awwal / 24 September the first Friday prayer was held in the Ranuna valley; the same day they reached Medina and settled in the house of Abu Ayyub al-Ansari.']],
  'medine-ilk': ['First Steps in Medina',
   'A mosque was built, and the Muhajirun and Ansar became brothers.',
   [['The Prophet’s Mosque', 'The first thing they did was build a mosque.'], ['Brotherhood', 'The Muhajirun and Ansar were made brothers.'], ['The Medina Charter', 'A document protecting everyone’s rights in Medina was written.']],
   'In Medina the Prophet’s Mosque was built, brotherhood (mu’akhat) was established, and common life was organised by the Medina Charter.',
   [['The Prophet’s Mosque', 'The mosque became a centre of worship, education and administration; the Suffa was given to poor emigrants.'], ['Mu’akhat', 'In the 1st year of the Hijra (Rajab / January 623) brotherhood was established between the Muhajirun and the Ansar.'], ['The Medina Charter', 'With the Medina Charter drawn up in the 1st year (Ramadan / March 623), the boundaries of the Medina sanctuary were set.']],
   [['What is the brotherhood between Muhajirun and Ansar called?', ['Mu’akhat', 'Pledge', 'Hudaybiyya'], 'Mu’akhat.'], ['Which was the first social contract made in Medina?', ['The Medina Charter', 'Hudaybiyya', 'The Farewell Sermon'], 'The Medina Charter.']],
   ['The Prophet’s Mosque was built by the Prophet himself as one of the first activities after the Hijra (it is one of the two mosques he built himself; the other is Quba). It stood at the centre of all his activities in Medina and became a model for later mosques.', 'Mu’akhat means “taking someone as a brother”: besides social commands like spreading the greeting of peace, feeding the hungry and building a mosque, the Meccan Companions were declared brothers first among themselves and then with some of the Ansar. Abu Bakr–Umar, Uthman–Abd al-Rahman ibn Awf, Talha–Zubayr and Sa‘d ibn Abi Waqqas–Mus‘ab ibn Umayr were among these pairs.', 'The Medina Charter was drawn up soon after the Hijra among the Muslims, Jews and polytheist Arabs of Medina. Its full text survives in Ibn Hisham’s Sira; the literature also calls it the “Medina Agreement” or “Medina constitution”.']],
  bedir: ['The Battle of Badr',
   'The few Muslims defeated the many polytheists with Allah’s help.',
   [['They met at Badr', 'The Muslims were about 300 and the polytheists about 1,000.'], ['Prayer', 'The Prophet prayed to Allah all night.'], ['Victory', 'The Muslims won.']],
   'On 17 Ramadan 2 / 13 March 624 at Badr, the Muslims fought and defeated the thousand-strong Quraysh army led by Abu Jahl.',
   [['Cause', 'The Messenger set out to intercept Abu Sufyan’s trade caravan returning from Syria at Badr; when the caravan escaped, Quraysh still marched with a thousand men.'], ['The battle', 'The outnumbered Muslims won a victory over a stronger enemy.'], ['Prisoners', 'Literate prisoners were released after teaching Muslim children to write.']],
   [['When was the Battle of Badr fought?', ['In the 2nd year of the Hijra', 'In the 6th year of the Hijra', 'Before the Hijra'], 'In the 2nd year of the Hijra (624).'], ['Who won at Badr?', ['The Muslims', 'The polytheists', 'It was a draw'], 'The Muslims won.']],
   ['Badr was a small town about 160 km southwest of Medina and 30 km from the Red Sea coast, where the Medina–Mecca road meets the Syrian caravan road; a fair lasting eight days was held there every year from the start of Dhu al-Qa‘da.', 'In the 2nd year of the Hijra (624) a large Qurayshi trade caravan under Abu Sufyan was returning from Syria. The Prophet gathered his Companions to meet the caravan at Badr. Abu Sufyan learned of the raid, asked for help and escaped by the coast road; despite learning the caravan was safe, the Qurayshis marched on Badr with about 1,000 men under Abu Jahl. The battle took place on 17 Ramadan 2 / 13 March 624.', 'Badr is one of the two battles named in the Qur’an (the other is Hunayn).']],
  uhud: ['The Battle of Uhud',
   'When the archers did not obey the order, the outcome changed.',
   [['The archers', 'The Prophet told the archers not to leave the hill.'], ['The turn', 'Some archers left the hill and the enemy struck from behind.'], ['The lesson', 'Hamza was martyred; the importance of obeying orders became clear.']],
   'On 7 or 11 Shawwal 3 (March 625) about 700 Companions met the enemy at Uhud; Abdullah ibn Ubayy had turned back with about 300 men. When the archers left their positions the Muslims were in trouble.',
   [['Start of the battle', 'The Muslims gained the upper hand.'], ['The archers’ post', 'Despite the Prophet’s order, many archers left the hill for the spoils; Khalid ibn al-Walid attacked from behind.'], ['Losses', 'About seventy Companions, including Hamza, were martyred; the Prophet was also wounded.']],
   [['Which hill were the archers placed on at Uhud?', ['Aynayn', 'Hira', 'Safa'], 'On the hill of Aynayn.'], ['Which uncle of the Prophet was martyred at Uhud?', ['Hamza', 'Abu Talib', 'Abbas'], 'Hamza.']],
   ['Mount Uhud lies north of Medina, about 5 km from the Prophet’s Mosque; it is a lone mountain 8 km long and 720 m high, dark red in appearance. The Prophet said, “Uhud loves us and we love Uhud.”', 'The Prophet at first did not want to fight outside Medina; at the insistence of some Companions they went out to Uhud. When Abdullah ibn Ubayy turned back with about 300 men on the way, 700 Companions reached the foot of Uhud and met the enemy on 7 or 11 Shawwal 3 (23 or 27 March 625).']],
  hendek: ['The Battle of the Trench',
   'The Muslims protected the city by digging a trench.',
   [['The siege', 'Enemy armies came to besiege Medina.'], ['The trench', 'On Salman al-Farisi’s idea, a trench was dug around the city.'], ['The storm', 'Cold and a storm forced the enemy to retreat.']],
   'Between Shawwal and Dhu al-Qa‘da 5 (March–April 627) the confederates of Quraysh, various Arab tribes and Banu Nadir besieged Medina; on Salman al-Farisi’s suggestion a trench was dug.',
   [['The confederates', 'A combined army of Quraysh, Ghatafan and Jewish tribes marched on Medina.'], ['The trench', 'On Salman al-Farisi’s suggestion a trench was dug on the open side of the city.'], ['Outcome', 'As the siege dragged on, the enemy withdrew because of cold, a storm and cracks in their alliance.']],
   [['Who gave the idea of the trench?', ['Salman al-Farisi', 'Bilal', 'Abu Dharr'], 'Salman al-Farisi.'], ['Why did the enemy withdraw in the Battle of the Trench?', ['The Muslims came out and defeated them', 'Because of cold and a storm', 'They went to the Ka‘ba'], 'The siege dragged on, and cold and a storm came.']],
   ['The war began at the end of Shawwal in the 5th year of the Hijra (March 627) and ended on 23 Dhu al-Qa‘da (15 April). It is called the Trench because the city was defended with trenches dug around it.', 'On the attacking side were Quraysh, the Jews of Khaybar, Ghatafan, Fazara, Banu Asad, Banu Sulaym and others; as the Qur’an calls these groups “ahzab” (confederates), the war is also called the Battle of the Confederates. Surat al-Ahzab (the 33rd chapter) refers to this siege in verses 20 and 22. The idea of the trench came from Salman al-Farisi.']],
  hudeybiye: ['The Treaty of Hudaybiyya',
   'They set out for umra but the Meccans did not let them in; a peace treaty was made.',
   [['On the way to umra', 'The Muslims marched toward Mecca to perform umra.'], ['A barrier', 'The Meccans did not let them enter.'], ['The treaty', 'A 10-year no-war treaty was made; Allah called it a “clear victory”.']],
   'On Dhu al-Qa‘da 6 (March 628) the Muslims, 1,400–1,500 strong, set out for umra and made a treaty with Quraysh at Hudaybiyya; Surat al-Fath was revealed on this occasion.',
   [['The Pledge of Ridwan', 'On the news that Uthman had been killed, a pledge was taken under a tree.'], ['The treaty', 'No war for ten years; the Muslims would return this year and perform umra the next.'], ['Result', 'This treaty, called a “clear victory” in Surat al-Fath, accelerated the spread of Islam.']],
   [['How many years of peace did the Hudaybiyya treaty provide?', ['2', '10', '30'], 'Ten years.'], ['Which chapter was revealed after Hudaybiyya?', ['Al-Fath', 'Al-Ma‘un', 'Al-Ikhlas'], 'Surat al-Fath.']],
   ['Hudaybiyya is 17 km west of Mecca on the old Jeddah road. It takes its name from the tree under which the Pledge of Ridwan was made (or from a nearby well).', 'The Prophet left Medina on Dhu al-Qa‘da 6 (March 628) with 1,400–1,500 people for umra. Quraysh sent a cavalry unit of 200 under Khalid ibn al-Walid. When Uthman, sent to Mecca as envoy, was detained, the Pledge of Ridwan was taken; then the treaty was signed and Surat al-Fath was revealed.', 'The treaty is called “fath mubin” (a clear victory): in the two years until the conquest of Mecca, more people became Muslims than in all the eighteen years before.']],
  fetih: ['The Conquest of Mecca',
   'The Muslims entered Mecca. The Prophet forgave everyone.',
   [['A great army', 'An army of ten thousand marched toward Mecca.'], ['The idols were destroyed', 'The Ka‘ba was cleansed of idols.'], ['Forgiveness', 'He said, “No blame on you today; go, you are all free.”']],
   'When Quraysh broke the Hudaybiyya treaty, the Prophet set out on 13 Ramadan 8 / 4 January 630; Mecca was conquered on 20 Ramadan / 11 January 630.',
   [['Cause', 'When Quraysh’s ally broke the Hudaybiyya agreement, the Muslims marched on Mecca.'], ['The conquest', 'The city was entered with almost no fighting; the Ka‘ba was cleansed of idols.'], ['General amnesty', 'The Qurayshis were told, “There is no blame on you today; go, you are all free.”']],
   [['When was Mecca conquered?', ['In the 8th year of the Hijra', 'In the 2nd year of the Hijra', 'Before the Hijra'], 'In the 8th year of the Hijra (630).'], ['What did the Prophet do to the Meccans?', ['Punished them', 'Forgave them', 'Exiled them'], 'He declared a general amnesty.']],
   ['When the Qurayshi polytheists violated the Hudaybiyya Treaty, Abu Sufyan tried to save the peace. The Prophet set out for the conquest of Mecca on 13 Ramadan 8 / 4 January 630; Mecca was conquered on 20 Ramadan / 11 January 630. The Banu Sulaym and Banu Ghifar tribes also joined the conquest under Khalid ibn al-Walid.', 'Shortly before the conquest (Safar 8) Khalid ibn al-Walid, Amr ibn al-As and Uthman ibn Talha had become Muslims. After Mecca came the battles of Hunayn (11 Shawwal / 1 February) and Ta’if.']],
  veda: ['The Farewell Pilgrimage',
   'On his last pilgrimage the Prophet delivered a great sermon to the people.',
   [['Arafat', 'Thousands of Muslims gathered at Arafat.'], ['The Farewell Sermon', 'He spoke about human rights and brotherhood.'], ['The religion was completed', 'The verse “Today I have completed your religion” came down.']],
   'In the 10th year of the Hijra (632) the Prophet left Medina on 26 Dhu al-Qa‘da and delivered the Farewell Sermon at Arafat on 9 Dhu al-Hijja / 7 March to more than 120,000 Companions.',
   [['The pilgrimage', 'The Prophet taught the rites of hajj: “Take your rites from me.”'], ['The Farewell Sermon', 'Beginning with the words that all people descended from the same father and mother are equal, the sermon dwelt mainly on human rights.'], ['The verse', 'The verse “Today I have completed your religion for you” came down.']],
   [['Where was the Farewell Sermon delivered?', ['Arafat', 'Mina', 'Medina'], 'At Arafat.'], ['When was the Farewell Pilgrimage?', ['The 10th year of the Hijra', 'The 5th year of the Hijra', 'Before the Hijra'], 'The 10th year of the Hijra (632).']],
   ['The Prophet left Medina for the Farewell Pilgrimage on 26 Dhu al-Qa‘da / 23 February. On 9 Dhu al-Hijja / 7 March 632 he delivered the Farewell Sermon in the Arafat valley to more than 120,000 Companions; on 14 Dhu al-Hijja / 12 March he performed the farewell circumambulation.', 'The sermon began with the words “All people descended from the same father and mother are equal” and mainly dwelt on human rights. After the sermon, the verse 5:3, announcing that the religion was completed, was revealed. Having completed the hajj, the Prophet returned to Medina.']],
  hastalik: ['Final Illness and Passing',
   'The Prophet fell ill, had Abu Bakr lead the prayer, and passed away.',
   [['Illness', 'He fell ill in the month of Safar.'], ['Abu Bakr as imam', 'Abu Bakr led the prayer.'], ['Passing', 'He passed away on a Monday in Rabi‘ al-Awwal.']],
   'He fell ill with a severe headache and fever on 27 Safar 11 (24 May 632); according to the DİA chronology he passed away on Monday, 13 Rabi‘ al-Awwal / 8 June 632 and was buried the next day (some accounts say 12 Rabi‘ al-Awwal).',
   [['The illness', 'He was cared for in Aisha’s room and gave some instructions.'], ['Leading the prayer', 'During his illness he assigned Abu Bakr to lead the prayer.'], ['His passing', 'His body was lowered into the grave dug where he passed away by Ali, al-Fadl, Qutham and Usama.']],
   [['On which day did the Prophet pass away?', ['Monday', 'Friday', 'Sunday'], 'According to the DİA chronology, on Monday.'], ['Who led the prayer during his illness?', ['Umar', 'Abu Bakr', 'Ali'], 'Abu Bakr.']],
   ['After the Farewell Pilgrimage, in Safar, Usama ibn Zayd was appointed commander of the army to go to Syria. The Prophet fell ill with a severe headache and fever on Sunday, 27 Safar / 24 May 632. During his illness he asked Abu Bakr to lead the prayer.', 'According to the DİA chronology he passed away on Monday, 13 Rabi‘ al-Awwal / 8 June 632 and was buried the next day. On the basis of a hadith Abu Bakr narrated, his body was lowered into the grave dug where he died by Ali, al-Fadl, Qutham and Usama.']],
  ebubekir: ['Abu Bakr',
   'Abu Bakr became the first caliph. The Qur’an began to be gathered into a book.',
   [['Chosen as caliph', 'The Muslims chose Abu Bakr as caliph.'], ['The Ridda wars', 'The state’s order was protected against those who refused to pay zakat.'], ['The Qur’an was gathered', 'The Qur’an was brought together in one written copy.']],
   'The first caliph, chosen at the Saqifa after the Prophet’s death; between 632 and 634 he led the state and the gathering of the Qur’an into one copy.',
   [['The election', 'After the Prophet’s death he was chosen caliph at Saqifat Banu Sa‘ida.'], ['The Ridda wars', 'He fought against those who denied zakat and against false prophets.'], ['Compiling the Qur’an', 'After many reciters were martyred at Yamama, the Qur’an was gathered under the direction of Zayd ibn Thabit.']],
   [['Who was the first caliph?', ['Umar', 'Abu Bakr', 'Uthman'], 'Abu Bakr.'], ['Who led the work of gathering the Qur’an?', ['Zayd ibn Thabit', 'Bilal', 'Hamza'], 'Zayd ibn Thabit.']],
   ['Abu Bakr was born in Mecca about three years after the Elephant incident. When he learned after the Prophet’s death that the Ansar had gathered at Saqifat Banu Sa‘ida to discuss the caliphate, he went there with Umar; against the idea of choosing one leader from the Ansar and one from the Muhajirun, he argued for preserving the unity of Islam, and he was chosen caliph.', 'Putting the Qur’an into the form of a mushaf during his caliphate was, in DİA’s words, one of his greatest services to Islam; Umar had persuaded him to do it.']],
  omer: ['Umar',
   'Great conquests were made, and the Hijri calendar began.',
   [['Conquests', 'Damascus, Jerusalem and Egypt were conquered.'], ['The calendar', 'The calendar was made with the Hijra year as its starting point.'], ['Justice', 'Umar was known for his justice.']],
   'In Umar’s time Syria, Iraq and Egypt were conquered; the diwan system and the Hijri calendar were adopted.',
   [['Conquests', 'Victories at Yarmouk (636) and Qadisiyya (636), the surrender of Jerusalem (637), the conquest of Egypt (641).'], ['State organisation', 'The diwan, provinces, judgeship and a salary system were established.'], ['The Hijri calendar', 'The Hijra was adopted as the starting point of the calendar.']],
   [['Which event is the start of the Hijri calendar?', ['The Hijra', 'Badr', 'The Conquest'], 'The Hijra.'], ['What is Umar’s title?', ['Al-Faruq', 'Al-Siddiq', 'Dhu al-Nurayn'], 'Al-Faruq (the one who distinguishes right from wrong).']],
   ['Umar was born in Mecca about thirteen years after the Elephant incident. He supported Abu Bakr’s being chosen caliph at the Saqifa; it was also he who persuaded Abu Bakr to have the Qur’an gathered in a mushaf.', 'During his caliphate the conquests of Syria and Iraq accelerated; Antioch, Urfa, Raqqa and Nusaybin surrendered to the Muslims in quick succession. When Jerusalem was besieged, Patriarch Sophronius said he wished to hand the keys of the city to Umar, who was at Jabiya.']],
  osman: ['Uthman',
   'The Qur’an was copied and sent to the cities. Then the unrest that followed had sad consequences.',
   [['The mushafs', 'Copies of the Qur’an were made and sent out.'], ['First naval expedition', 'The Muslim fleet sailed to Cyprus.'], ['Unrest', 'Because of the disturbances, Uthman was martyred.']],
   'The mushaf was copied and sent to the cities, Cyprus was conquered (649), and the ensuing unrest ended with Uthman’s martyrdom (656).',
   [['The mushaf', 'When differences in recitation grew, a committee was formed under Zayd ibn Thabit; the mushafs were copied and sent out.'], ['Conquests', 'The first naval expedition to Cyprus took place (649).'], ['Unrest and martyrdom', 'After the revolts his house was besieged and he was martyred in Dhu al-Hijja 35 / 656.']],
   [['What was done for the Qur’an in Uthman’s time?', ['Mushafs were copied and sent out', 'The Qur’an was banned', 'Memorising the Qur’an was banned'], 'The mushafs were copied.'], ['What is Uthman’s title?', ['Dhu al-Nurayn', 'Al-Faruq', 'Al-Siddiq'], 'Dhu al-Nurayn (“possessor of two lights”).']],
   ['Uthman was born in Ta’if six years after the Elephant incident; he was the son of one of Quraysh’s richest merchants. He was chosen caliph from among the six-man council appointed by Umar.', 'To prevent disputes caused by differences in recitation, he copied the Qur’an, which had been put into a mushaf in Abu Bakr’s time, in five or seven copies, and sent one each to Mecca, Basra, Kufa, Damascus, Yemen and Bahrain, leaving the “imam mushaf” in Medina.', 'The revolt that began with complaints led to Uthman’s killing, and then to the civil wars of the Camel and Siffin. The sources describe this revolt in great detail but with contradictory accounts.']],
  ali: ['Ali',
   'The fourth caliph, Ali, made Kufa the capital. Wars broke out among Muslims.',
   [['Kufa', 'Kufa became the capital.'], ['Camel and Siffin', 'Muslims fought one another.'], ['Martyrdom', 'He was martyred in Kufa in the month of Ramadan.']],
   'In the caliphate of Ali (656–661) the battles of the Camel (656) and Siffin (657) took place and the Kharijites emerged; he was martyred in 661.',
   [['The caliphate', 'He was chosen caliph after Uthman’s martyrdom; he moved the capital to Kufa.'], ['Civil wars', 'Muslims fought one another in the Camel (656), Siffin (657) and Nahrawan (658).'], ['Martyrdom', 'He was martyred in Kufa on Ramadan 40 / 661 by Ibn Muljam.']],
   [['What is the correct order of the four caliphs?', ['Abu Bakr, Umar, Uthman, Ali', 'Umar, Abu Bakr, Ali, Uthman', 'Ali, Uthman, Umar, Abu Bakr'], 'Abu Bakr, Umar, Uthman, Ali.'], ['Which city did Ali make his capital?', ['Kufa', 'Damascus', 'Mecca'], 'Kufa.']],
   ['Ali was the youngest son of Abu Talib. When famine struck Mecca, the Prophet took him under his care to lighten his uncle’s burden; Ali grew up with him from the age of five until the Hijra.', 'The Battle of the Camel was fought on 15 Jumada al-Akhira 36 / 9 December 656 at Hurayba near Basra; Ali won, and many Muslims, including Talha and Zubayr, died. At Siffin (Dhu al-Hijja 36 / June 657) he faced Mu‘awiya; when mushafs were tied to spear tips, arbitration came up, and those who opposed it split away as the Kharijites.']]
 }
};
